ion"><h2 class="h6 mb-3">Tujuan atau keterangan</h2><div class="workspace-floating-field"><textarea name="purpose" class="form-control" rows="4" maxlength="2000">{{ old('purpose') }}</textarea><label class="form-label">Keterangan umum</label></div></section></div><div class="col-lg-6"><section class="workspace-form-section"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h6 mb-1">Rincian biaya</h2><p class="text-secondary small mb-0">Satu pengajuan dapat memiliki beberapa nota.</p></div><button type="button" class="btn btn-outline-primary btn-sm" id="add-claim-item">+ Tambah rincian</button></div><div id="claim-items">@php($items = old('items', [['receipt_date'=>'','activity_date'=>'','category'=>'','description'=>'','currency'=>'IDR','amount'=>'','attachment_reference'=>'']]))@foreach($items as $index => $item)<div class="border rounded-3 p-3 mb-3 claim-item"><div class="d-flex justify-content-between align-items-center mb-3"><span class="badge rounded-pill bg-primary-subtle text-primary">Rincian {{ $loop->iteration }}</span><button type="button" class="btn btn-sm btn-outline-danger remove-claim-item">Hapus</button></div><div class="row g-3"><div class="col-md-6"><div class="workspace-floating-field"><input type="date" name="items[{{ $index }}][receipt_date]" value="{{ $item['receipt_date'] ?? '' }}" class="form-control"><label class="form-label">Tanggal nota</label></div></div><div class="col-md-6"><div class="workspace-floating-field"><input type="date" name="items[{{ $index }}][activity_date]" value="{{ $item['activity_date'] ?? '' }}" class="form-control"><label class="form-label">Tanggal kegiatan</label></div></div><div class="col-md-6"><div class="workspace-floating-field"><input name="items[{{ $index }}][category]" value="{{ $item['category'] ?? '' }}" class="form-control" required><label class="form-label">Jenis kebutuhan <span class="text-danger">*</span></label></div></div><div class="col-md-6"><div class="workspace-floating-field"><select name="items[{{ $index }}][currency]" class="form-select"><option value="IDR">IDR</option><option value="USD">USD</option><option value="SGD">SGD</option></select><label class="form-label">Mata uang</label></div></div><div class="col-md-6"><div class="workspace-floating-field"><input type="number" step="0.01" min="0.01" name="items[{{ $index }}][amount]" value="{{ $item['amount'] ?? '' }}" class="form-control" required><label class="form-label">Nominal <span class="text-danger">*</span></label></div></div><div class="col-md-6"><div class="workspace-floating-field"><input name="items[{{ $index }}][attachment_reference]" value="{{ $item['attachment_reference'] ?? '' }}" class="form-control"><label class="form-label">Reference nota</label></div></div><div class="col-12"><div class="workspace-floating-field"><textarea name="items[{{ $index }}][description]" class="form-control" rows="2" required>{{ $item['description'] ?? '' }}</textarea><label class="form-label">Deskripsi <span class="text-danger">*</span></label></div></div></div></div>@endforeach</div><div class="border-top pt-3 d-flex justify-content-between"><span class="fw-semibold">Total pengajuan</span><strong id="claim-total">IDR 0,00</strong></div></section></div></div></div><div class="card-footer bg-white d-flex justify-content-end gap-2"><a href="{{ route('workspace.hris.claims') }}" class="btn btn-light">Batal</a><button class="btn btn-primary">Kirim pengajuan</button></div></form>
<script>(()=>{const l=document.getElementById('claim-items'),a=document.getElementById('add-claim-item'),t=document.getElementById('claim-total');let i=l.querySelectorAll('.claim-item').length;const u=()=>{let s=0;l.querySelectorAll('input[name$="[amount]"]').forEach(e=>s+=Number(e.value||0));t.textContent='IDR '+s.toLocaleString('id-ID',{minimumFractionDigits:2,maximumFractionDigits:2});l.querySelectorAll('.claim-item').forEach((e,n)=>e.querySelector('.badge').textContent='Rincian '+(n+1));};a.onclick=()=>{const e=l.querySelector('.claim-item').cloneNode(true);e.querySelectorAll('input,textarea').forEach(x=>{x.value='';x.name=x.name.replace(/items\[\d+\]/,'items['+i+']')});e.querySelectorAll('select').forEach(x=>x.name=x.name.replace(/items\[\d+\]/,'items['+i+']'));l.appendChild(e);i++;u()};l.onclick=e=>{if(e.target.closest('.remove-claim-item')&&l.querySelectorAll('.claim-item').length>1){e.target.closest('.claim-item').remove();u()}};l.oninput=u;u()})();</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('claim-form');
    const send = form?.querySelector('.card-footer button[type="submit"]');
    if (!form || !send) return;
    const isDraft = @json($isDraft);
    if (isDraft) {
        const claimData = @json($claimData);
        Object.entries(claimData).forEach(([key, value]) => { const field = form.querySelector(`[name="${key}"]`); if (field && value !== null) field.value = value; });
        form.action = @json($claimAction);
        const method = document.createElement('input');
        method.type = 'hidden'; method.name = '_method'; method.value = 'PUT'; form.append(method);
        const draftItems = @json($draftItems);
        const rows = form.querySelector('#claim-items');
        for (let n = 1; n < draftItems.length; n += 1) document.getElementById('add-claim-item')?.click();
        draftItems.forEach((item, n) => {
            const row = rows?.querySelectorAll('.claim-item')[n];
            if (!row) return;
            Object.entries(item).forEach(([key, value]) => { const field = row.querySelector(`[name$="[${key}]"]`); if (field) field.value = value ?? ''; });
        });
    }
    send.name = 'action';
    send.value = 'submit';
    const draft = document.createElement('button');
    draft.type = 'submit';
    draft.name = 'action';
    draft.value = 'draft';
    draft.className = 'btn btn-outline-secondary';
    draft.textContent = 'Simpan draft';
    send.parentElement.insertBefore(draft, send);
    form.addEventListener('submit', (event) => {
        if (event.submitter?.value === 'submit' && !window.confirm('Kirim pengajuan reimbursement untuk diproses? Setelah dikirim, draft tidak dapat dihapus lagi.')) {
            event.preventDefault();
            event.stopImmediatePropagation();
        }
    }, true);
});
</script>
